'use strict';

import { createError, MISSING_DOC } from 'pouchdb-errors';

import { DOC_STORE, META_LOCAL_STORE } from './util';

import { isLocalId } from 'pouchdb-adapter-utils';
import { latest as getLatest } from 'pouchdb-merge';

export default function (txn, id, opts, callback) {
  if (txn.error) {
    return callback(txn.error);
  }

  // N.B. this check is only required to allow getAttachment() to work
  // on local docs.  It's debatable if local docs should even be allowed
  // attachments in the first place, and there is inconsistency in
  // implementation between different adapters.  Consider removing this
  // support in future.
  const docStore = isLocalId(id) ? META_LOCAL_STORE : DOC_STORE;

  txn.txn.objectStore(docStore).get(id).onsuccess = function (e) {
    var doc = e.target.result;
    var rev;
    if (!opts.rev) {
      rev = (doc && doc.rev);
    } else {
      rev = opts.latest ? getLatest(opts.rev, doc) : opts.rev;
    }

    if (!doc || (doc.deleted && !opts.rev) || !(rev in doc.revs)) {
      callback(createError(MISSING_DOC, 'missing'));
      return;
    }

    var result = doc.revs[rev].data;
    result._id = doc.id;
    result._rev = rev;

    // WARNING: expecting possible old format
    // TODO: why are we passing the transaction in the context?
    //       It's not clear we ever thread these txns usefully
    callback(null, {
      doc: result,
      metadata: doc,
      ctx: txn
    });
  };
}
